//! Retry configuration.

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self { max_attempts, base_delay_ms, max_delay_ms }
    }
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self { max_attempts: 3, base_delay_ms: 100, max_delay_ms: 1_000 }
    }
}

//! Error taxonomy for the job runner.

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => return Err(error),
            Err(_) => {
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let config = RetryConfig::new(5, 10, 25);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 5 { Err(RetryError::Transient("temporary".into())) } else { Ok(()) }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&RetryConfig::new(5, 10, 100), &mut sleeper, || {
            Err(RetryError::Permanent("invalid".into()))
        });
        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let config = RetryConfig::new(2, 1, 10);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("down".into()))
        });
        assert!(result.is_err());
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![1]);
    }
}

# jobrunner

Small job runner with a configurable, bounded exponential retry policy.

## Retry policy

`run_job` keeps its public signature and accepts a `RetryConfig`, a sleeper,
and a job closure. The first invocation counts toward `max_attempts`. Only
`RetryError::Transient` failures are retried; `RetryError::Permanent` failures
are returned immediately. Before each retry, the runner sleeps for the current
delay, starting at `base_delay_ms` and doubling after every retry. Delay growth
is capped at `max_delay_ms`.

For example:

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig::new(4, 100, 1_000);
let mut sleeper = FakeSleeper::default();
let result = run_job(&config, &mut sleeper, || {
    Err(RetryError::Transient("temporary outage".into()))
});
assert!(result.is_err());
assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
```

`RetryConfig::default()` allows three total attempts, with a 100 ms base delay
and a 1,000 ms maximum delay. A zero `max_attempts` is treated as one attempt.

