use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_then_success_retries_and_preserves_result() {
    let config = RetryConfig::new(3, 7, 50);
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        if attempts == 1 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![7]);
}

#[test]
fn permanent_failure_is_not_retried() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&RetryConfig::new(10, 1, 10), &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}

